// VideoServiceHandler is an implementation of the transcodely.v1.VideoService service.
type VideoServiceHandler interface {
	// Create a presigned upload URL for direct browser/client upload.
	// Returns a Video in "uploading" status and a time-limited upload URL.
	CreateUpload(context.Context, *connect.Request[v1.CreateUploadRequest]) (*connect.Response[v1.CreateUploadResponse], error)
	// Signal that a client-side upload has completed.
	// Triggers processing (probe + transcode) for the uploaded file.
	CompleteUpload(context.Context, *connect.Request[v1.CompleteUploadRequest]) (*connect.Response[v1.CompleteUploadResponse], error)
	// Create a hosted video from a publicly-reachable http(s) URL in one call.
	// The API fetches nothing itself: it records the video in "processing" and
	// hands the URL to the transcoding pipeline, which downloads it at run time.
	// Returns a Video in "processing" status (no upload step). Playback/embed
	// URLs populate once the video reaches "ready" (subscribe to video.ready or
	// Watch). The app must have managed hosting enabled.
	CreateFromUrl(context.Context, *connect.Request[v1.CreateFromUrlRequest]) (*connect.Response[v1.CreateFromUrlResponse], error)
	// Create a multipart upload for large files (up to 5GB).
	// Returns a Video in "uploading" status, an S3 upload_id, and presigned
	// URLs for the first batch of parts (up to 50).
	CreateMultipartUpload(context.Context, *connect.Request[v1.CreateMultipartUploadRequest]) (*connect.Response[v1.CreateMultipartUploadResponse], error)
	// Get fresh presigned URLs for specific part numbers of an in-progress
	// multipart upload. Use this to fetch URLs in batches or refresh expired ones.
	GetUploadPartUrls(context.Context, *connect.Request[v1.GetUploadPartUrlsRequest]) (*connect.Response[v1.GetUploadPartUrlsResponse], error)
	// Complete a multipart upload by providing ETags from all uploaded parts.
	// Assembles the parts in S3, then triggers processing (probe + transcode).
	CompleteMultipartUpload(context.Context, *connect.Request[v1.CompleteMultipartUploadRequest]) (*connect.Response[v1.CompleteMultipartUploadResponse], error)
	// Abort a multipart upload, cleaning up S3 parts and deleting the video record.
	AbortMultipartUpload(context.Context, *connect.Request[v1.AbortMultipartUploadRequest]) (*connect.Response[v1.AbortMultipartUploadResponse], error)
	// Get a video by ID.
	Get(context.Context, *connect.Request[v1.GetVideoRequest]) (*connect.Response[v1.GetVideoResponse], error)
	// List videos with optional filtering.
	List(context.Context, *connect.Request[v1.ListVideosRequest]) (*connect.Response[v1.ListVideosResponse], error)
	// Update a video's mutable fields (title, description, tags, visibility).
	Update(context.Context, *connect.Request[v1.UpdateVideoRequest]) (*connect.Response[v1.UpdateVideoResponse], error)
	// Delete a video and all associated storage.
	Delete(context.Context, *connect.Request[v1.DeleteVideoRequest]) (*connect.Response[v1.DeleteVideoResponse], error)
	// Watch a video for real-time status updates. Streams the current state immediately,
	// then pushes updates as the video progresses through processing.
	// Stream closes automatically when the video reaches a terminal state.
	Watch(context.Context, *connect.Request[v1.WatchVideoRequest], *connect.ServerStream[v1.WatchVideoResponse]) error
	// Get usage summary for the current billing period or a specific month.
	GetUsage(context.Context, *connect.Request[v1.GetUsageRequest]) (*connect.Response[v1.GetUsageResponse], error)
	// Get playback analytics for a single video: plays, watch time, and unique
	// viewers aggregated per UTC day. Stats are collected from a lightweight,
	// best-effort playback beacon and rolled up hourly, so recent activity may
	// lag by up to an hour.
	GetStats(context.Context, *connect.Request[v1.GetStatsRequest]) (*connect.Response[v1.GetStatsResponse], error)
	// List an app's top videos ranked by plays over a date range.
	ListTopVideos(context.Context, *connect.Request[v1.ListTopVideosRequest]) (*connect.Response[v1.ListTopVideosResponse], error)
	// Get ready-to-paste SEO markup for showing a video on your own page:
	// schema.org VideoObject JSON-LD (with chapter key moments when the video
	// has insights), a video sitemap entry, and a server-renderable HTML
	// fragment with the summary, chapters and full transcript. The video must be
	// ready and public or unlisted; other videos are refused with
	// failed_precondition.
	GetSeoMarkup(context.Context, *connect.Request[v1.GetSeoMarkupRequest]) (*connect.Response[v1.GetSeoMarkupResponse], error)
	// Generate AI insights (title suggestions, summary, key points, chapters,
	// questions, key terms, highlights, topics) from a hosted video's existing
	// AI captions, without transcribing again. Billed EUR 0.02 per video plus
	// EUR 0.005 per minute of source, charged only when the insights become
	// ready. Returns the entry in "pending"; it also appears on Video.insights,
	// and video.insights.ready or video.insights.failed fires when it finishes.
	//
	// While an entry for the same video and language is pending, the call
	// returns that entry and bills nothing new. Once it is ready or failed, a
	// new call generates (and bills) a new entry; it replaces the ready one
	// only when it becomes ready itself.
	//
	// Refused with failed_precondition and code captions_required when the
	// video has no AI captions, and insights_transcript_unavailable when the
	// caption track has no transcript.
	GenerateInsights(context.Context, *connect.Request[v1.GenerateInsightsRequest]) (*connect.Response[v1.GenerateInsightsResponse], error)
	// Cut highlight clips from a hosted video: up to max_count short MP4s
	// (default 5) around the verbatim quotes its ready AI insights picked
	// (TranscriptInsights.highlights; for a translated language, their
	// translations, which keep the same timings and so cut the same windows),
	// rendered at the video's top rendition's
	// codec and resolution. Returns the highlights in "pending"; they also
	// appear on Video.highlights, and video.highlights.ready (or
	// video.highlights.failed, when none could be rendered) fires once every
	// one of them has finished.
	//
	// Each highlight is rendered by its own clip job on the video
	// (input_video_id = the video, with a job-level clip), priced as its
	// rendered (clipped) length, measured to the millisecond, at your effective
	// encoding rate and nothing else: highlight clips carry no per-job
	// processing fee. The set is billed as one charge once every highlight in
	// it is ready or failed: the sum of its ready clips, rounded to the cent
	// once. A failed clip bills nothing. Those jobs count toward your
	// concurrency and queue limits and appear in your job list, each showing
	// its share of the set's charge.
	//
	// While any highlight of the video is pending, the call returns the
	// current highlights and bills nothing new. Once all are ready or failed, a
	// new call replaces them with a new set.
	//
	// Refused with failed_precondition: code highlights_require_insights when
	// the video has no ready AI insights (in the language), and
	// highlights_no_moments when they picked no quote inside the video; also
	// while the video is still processing or when the app's managed hosting is
	// off. Account refusals (spend limit, past due, suspended) are the same as
	// CreateJob's.
	GenerateHighlights(context.Context, *connect.Request[v1.GenerateHighlightsRequest]) (*connect.Response[v1.GenerateHighlightsResponse], error)
	// Translate a hosted video's existing AI captions into other languages,
	// without transcribing again. Creates one captions-only job on the video
	// (input_video_id = the video) that reads the transcript of the source
	// language's default caption style (VideoTextTrack.is_default) and
	// writes, per target language: a caption track (replacing any existing
	// auto-generated track of that language on completion), its transcript
	// renditions and, when the video streams as HLS, a caption rendition in
	// the manifest. With include_insights (default true) and ready insights in
	// the source language, the insights are translated too and appear as one
	// more Video.insights entry per language (video.insights.ready fires).
	//
	// Billed as the `captions_translation` fee: EUR 0.12 per source minute per
	// language, charged only for languages actually delivered; nothing else
	// (no captions fee, no per-job processing fee).
	//
	// While a translation job for this video and a target language is still
	// running, that language is not requested again: the response lists it
	// under in_flight with the job that carries it, and the new job (if any)
	// covers only the other languages. Once a job is terminal, a new call
	// translates (and bills) again and replaces the tracks.
	//
	// Refused with failed_precondition and code captions_required when the
	// video has no AI captions, insights_transcript_unavailable when the
	// source track has no transcript, and with invalid_argument
	// (parameter_invalid) when a target equals the source language or is not a
	// supported translation language (the violation lists the supported codes).
	// Refused with failed_precondition and code captions_job_in_flight while a
	// RestyleCaptions job on the source language is still running (it is about
	// to replace the cues the translation would follow); the message names
	// that job. Deployments without the feature refuse it with
	// `parameter_unsupported`.
	// Account refusals (spend limit, past due, suspended) are the same as
	// CreateJob's. Refused with unavailable and code translation_busy when the
	// call could not start within about 10 seconds because other caption
	// translations (of this video, or many at once) were being started at the
	// same moment: nothing was created or billed, and the same request can be
	// retried after a few seconds.
	//
	// Privacy: the caption TEXT (never the audio or video) is sent to Anthropic,
	// our AI subprocessor, to produce the translation; it is not used to train
	// models. Requesting a translation also enables the AI correction pass
	// described under SubtitleTrack.insights (same subprocessor, no charge).
	TranslateCaptions(context.Context, *connect.Request[v1.TranslateCaptionsRequest]) (*connect.Response[v1.TranslateCaptionsResponse], error)
	// Re-cuts a hosted video's existing AI captions into cues of a new cue
	// style (CueStyle), without transcribing again. The words and their
	// timings come from the language's stored transcript; only how they are
	// grouped into cues changes. Creates a captions-only job on the video
	// (job_id in the response; follow it with JobService.Get or the job.*
	// webhooks). Insights are kept as they are (the words do not change).
	//
	// A language keeps one caption track per style (VideoTextTrack.
	// style_variant, the preset of cue_style). When the language has no track
	// in the requested style yet, the job adds one next to the existing
	// styles: viewers can switch between them in the player, and the new one
	// is not the default unless make_default is set (adds_variant in the
	// response). When it has one, that track is re-cut in place. Either way
	// the track's caption file, its transcript renditions and, when the
	// video's HLS stream carries the language, its stream rendition are
	// written, its updated_at moves and its cue_style shows the new style. No
	// other style of the language is touched. Deployments that do not offer
	// several styles per language yet re-cut the language's default track in
	// place instead, whatever its style, and adds_variant is false.
	//
	// Translations are not re-cut: they keep their cues. When the default
	// style's cues change, its newer updated_at marks them as made from
	// captions that have since changed. Translate again (TranslateCaptions)
	// to bring them onto the new cues.
	//
	// Free: no captions, translation or processing fee is charged.
	//
	// Deployments whose workers do not cut by cue style yet refuse it with
	// invalid_argument and code `parameter_unsupported` on cue_style.
	//
	// Refused with failed_precondition and code captions_required when the
	// video has no AI captions or the chosen track is itself a translation,
	// insights_transcript_unavailable when the track has no transcript, and
	// captions_job_in_flight when a captions job (generation, translation or
	// another restyle) of the same language is still running on the video;
	// the message names that job. Refused with unavailable and code
	// translation_busy when the call could not start within about 10 seconds
	// because other caption jobs on the video were being started at the same
	// moment: nothing was created, and the same request can be retried after a
	// few seconds. Account refusals are the same as CreateJob's.
	RestyleCaptions(context.Context, *connect.Request[v1.RestyleCaptionsRequest]) (*connect.Response[v1.RestyleCaptionsResponse], error)
	// Makes another of a language's caption styles its default. The default
	// style is the one players select for the language and the one labelled
	// with the language name alone; the previous default stays available
	// under "<language> (<style>)". When the video streams as HLS, its master
	// playlist is rewritten so the language's default rendition plays the new
	// default style's captions, and the playlist is purged from the CDN.
	// Translations of the language become stale (VideoTextTrack.stale):
	// translate again to bring them onto the new default's cues. Free.
	//
	// Setting the current default again succeeds and changes nothing.
	// Refused with not_found when the video has no AI caption track of that
	// language in that style, and with failed_precondition and code
	// captions_job_in_flight while a captions job (generation, translation or
	// restyle) of the language is still running on the video; the message
	// names that job. Refused with unavailable and code translation_busy when
	// other caption changes on the video were being started at the same
	// moment, and caption_manifest_busy when the video's playlist kept
	// changing while it was being rewritten; nothing was changed, and the same
	// request can be retried after a few seconds.
	SetDefaultCaptionStyle(context.Context, *connect.Request[v1.SetDefaultCaptionStyleRequest]) (*connect.Response[v1.SetDefaultCaptionStyleResponse], error)
	// Removes one style of a language's AI captions: the caption track, its
	// entry in the video's HLS master playlist (purged from the CDN) and its
	// files. The default style cannot be removed, which also keeps a
	// language's only style: make another style the default first
	// (SetDefaultCaptionStyle), or regenerate the captions. Free.
	//
	// Refused with not_found when the video has no AI caption track of that
	// language in that style, with invalid_argument and code
	// parameter_invalid when that track is the language's default, and with
	// the same captions_job_in_flight, translation_busy and
	// caption_manifest_busy refusals as SetDefaultCaptionStyle.
	DeleteCaptionStyle(context.Context, *connect.Request[v1.DeleteCaptionStyleRequest]) (*connect.Response[v1.DeleteCaptionStyleResponse], error)
}

